ALTER TABLE "lesson_package_templates" ADD CONSTRAINT "lesson_package_templates_origin_shape_check" CHECK (("lesson_package_templates"."origin_type" is null and "lesson_package_templates"."origin_id" is null) or ("lesson_package_templates"."origin_type" = 'group_formation' and "lesson_package_templates"."origin_id" is not null));--> statement-breakpoint
