ALTER TABLE "lesson_package_versions" ADD CONSTRAINT "lesson_package_versions_origin_shape_check" CHECK (("lesson_package_versions"."origin_type" is null and "lesson_package_versions"."origin_id" is null) or ("lesson_package_versions"."origin_type" = 'group_formation' and "lesson_package_versions"."origin_id" is not null));--> statement-breakpoint
