ALTER TABLE "lesson_commerce_orders" ADD CONSTRAINT "lesson_commerce_orders_settlement_amount_check" CHECK ("lesson_commerce_orders"."deposit_applied_minor" >= 0 and "lesson_commerce_orders"."balance_due_minor" >= 0 and "lesson_commerce_orders"."amount_minor" = "lesson_commerce_orders"."deposit_applied_minor" + "lesson_commerce_orders"."balance_due_minor");--> statement-breakpoint
ALTER TABLE "lesson_commerce_orders" ADD CONSTRAINT "lesson_commerce_orders_awaiting_settlement_check" CHECK ("lesson_commerce_orders"."status" <> 'awaiting_settlement' or ("lesson_commerce_orders"."source_type" = 'group_formation' and "lesson_commerce_orders"."balance_due_minor" > 0 and "lesson_commerce_orders"."channel" = 'pending'));--> statement-breakpoint
ALTER TABLE "lesson_commerce_orders" ADD CONSTRAINT "lesson_commerce_orders_channel_check" CHECK ("lesson_commerce_orders"."channel" in ('pending','online','offline'));--> statement-breakpoint
