ALTER TABLE "lesson_commerce_orders" ADD CONSTRAINT "lesson_commerce_orders_channel_payment_check" CHECK (("lesson_commerce_orders"."channel" = 'pending' and "lesson_commerce_orders"."provider" is null and "lesson_commerce_orders"."payment_intent_id" is null and "lesson_commerce_orders"."payment_method" = 'pending') or ("lesson_commerce_orders"."channel" = 'online' and "lesson_commerce_orders"."provider" is not null and "lesson_commerce_orders"."payment_method" in ('wechat_pay','mock')) or ("lesson_commerce_orders"."channel" = 'offline' and "lesson_commerce_orders"."provider" is null and "lesson_commerce_orders"."payment_intent_id" is null and "lesson_commerce_orders"."payment_method" in ('cash','bank_transfer','wechat_transfer','other')));--> statement-breakpoint
ALTER TABLE "lesson_commerce_orders" ADD CONSTRAINT "lesson_commerce_orders_status_check" CHECK ("lesson_commerce_orders"."status" in ('awaiting_settlement','pending_payment','paid_pending_grant','completed','closed','grant_failed','refunding','refunded'));
